 const featureIndex=(kind==='Node'?gnnData.feature_names:gnnData.edge_feature_names).indexOf(feature),rows=kind==='Node'?gnnData.x:gnnData.edge_x,masks=kind==='Node'?gnnData.x_known:gnnData.edge_x_known;
