 const ids=kind==='Node'?indices.map(i=>gnnData.node_ids[i]):[...new Set(selectedEdges.flatMap(e=>[e.source,e.target]))];
 state.mode='gnn-feature';state.path=null;state.node=null;state.finding=null;state.relationship=null;state.selection={nodes:new Set(ids),...(selectedEdges?{edges:new Set(selectedEdges.map(e=>e.id))}:{})};
