if(gnnData?.feature_names){properties($('gnn-feature-summary'),{'Node features':gnnData.feature_names.length,'Edge features':gnnData.edge_feature_names.length,'Relationship types':gnnData.relation_names.length,'Nodes':gnnData.node_ids.length,'Edges':gnnData.edge_ids.length,'Missing-data masks':'Included'});}else add($('gnn-feature-summary'),'p',gnnData?.reason||'Re-export this report to include its feature inventory.','hint');
