let graphMotions=[],motionRevision=0,drawnSceneSize={nodes:0,edges:0};
function cancelGraphMotion(){motionRevision++;for(const animation of graphMotions)animation.cancel();graphMotions=[];$('graph').dataset.motionState='idle';$('graph').dataset.motionCount='0';}
function captureGraphScene(animate){
 const allowed=animate&&LinuxHoundGraph.motionAllowed(state.motion,state.graph.nodes.length,state.graph.edges.length);
 const previous={enabled:allowed,nodes:new Map(),edges:new Map()};
 if(allowed&&LinuxHoundGraph.motionAllowed(true,drawnSceneSize.nodes,drawnSceneSize.edges)){
  for(const el of $('graph').querySelectorAll('.graph-node[data-node-id]'))previous.nodes.set(el.dataset.nodeId,getComputedStyle(el).transform);
  for(const el of $('graph').querySelectorAll('.edge[data-edge-id]'))previous.edges.set(el.dataset.edgeId,{d:el.getAttribute('d'),computed:getComputedStyle(el).d});
 }
 cancelGraphMotion();return previous;
}
function animateGraphScene(previous){
 drawnSceneSize=state.mode==='summary'?{nodes:state.summary.groups.length+1,edges:state.summary.groups.length}:{nodes:state.graph.nodes.length,edges:state.graph.edges.length};
 if(!previous?.enabled)return;
 const options={duration:320,easing:'cubic-bezier(.22,1,.36,1)'};
 function motion(el,frames,extra={}){if(typeof el.animate!=='function')return;graphMotions.push(el.animate(frames,{...options,...extra}));}
 for(const [i,el]of [...$('graph').querySelectorAll('.graph-node[data-node-id]')].entries()){
  const end=getComputedStyle(el).transform,old=previous.nodes.get(el.dataset.nodeId),opacity=getComputedStyle(el).opacity;
  if(old&&old!==end)motion(el,[{transform:old},{transform:end}]);
  else if(!old)motion(el,[{opacity:0,transform:end+' scale(.9)'},{opacity,transform:end}],{delay:Math.min(i*14,120)});
 }
 const morph=typeof CSS!=='undefined'&&CSS.supports('d','path("M 0 0 L 1 1")'),hits=new Map([...$('graph').querySelectorAll('.edge-hit[data-edge-hit-id]')].map(el=>[el.dataset.edgeHitId,el]));
 for(const el of $('graph').querySelectorAll('.edge[data-edge-id]')){
  const old=previous.edges.get(el.dataset.edgeId),end=el.getAttribute('d');
  if(old&&old.d!==end&&morph&&(old.d.match(/[A-Za-z]/g)||[]).join('')===(end.match(/[A-Za-z]/g)||[]).join('')){
   const frames=[{d:old.computed},{d:'path("'+end+'")'}];motion(el,frames);
   const hit=hits.get(el.dataset.edgeId);if(hit)motion(hit,frames);
  }else if(!old)motion(el,[{opacity:0},{opacity:getComputedStyle(el).opacity}],{duration:260,delay:70});
 }
 for(const [i,el]of [...$('graph').querySelectorAll('.edge-label,.summary-edge-label')].entries())motion(el,[{opacity:0},{opacity:getComputedStyle(el).opacity}],{duration:200,delay:Math.min(i*9,90)});
 graphMotions=graphMotions.filter(animation=>animation.playState!=='finished');
 const revision=motionRevision,root=$('graph');root.dataset.motionState=graphMotions.length?'animating':'idle';root.dataset.motionCount=String(graphMotions.length);
 Promise.allSettled(graphMotions.map(animation=>animation.finished)).then(()=>{if(revision===motionRevision){root.dataset.motionState='idle';root.dataset.motionCount='0';graphMotions=[];}});
}
function addFlowParticles(){
 if(!state.motion||state.graph.edges.length>250)return;
 const curves=[...$('graph').querySelectorAll('.edge.highlight,.edge.relationship,.edge.incident,.summary-edge')].slice(0,32);
 for(const [i,curve] of curves.entries()){
  const particle=svg('circle',{r:2.4,class:'flow-particle',fill:curve.style.stroke||(curve.classList.contains('attack')?'#ff2636':'#d7e3e8')});
  const movement=svg('animateMotion',{dur:(2.8+i%4*.3)+'s',begin:(-i*.37)+'s',repeatCount:'indefinite',path:curve.getAttribute('d'),rotate:'auto'});
  particle.appendChild(movement);$('graph').appendChild(particle);
 }
}
