if(report.comparison){const comparison=report.comparison;add($('changes'),'p',comparison.statement,'hint');for(const status of ['removed_under_complete_coverage','incomplete_not_a_fix','added']){const items=(comparison.paths||{})[status]||[];add($('changes'),'h3',label(status)+' ('+items.length+')');for(const item of items){const card=add($('changes'),'div',undefined,'card');add(card,'p',item.summary);}}}else add($('changes'),'p','Export with --before to embed a coverage-aware hardening comparison.','hint');
